tokens_base:
:root{
  /* neutral scale — hue 240 */
  --n-950:oklch(14% .012 240); --n-925:oklch(17% .013 240); --n-900:oklch(20% .014 240);
  --n-850:oklch(24% .014 240); --n-800:oklch(28% .013 240); --n-700:oklch(38% .012 240);
  --n-600:oklch(48% .010 240); --n-500:oklch(66% .008 240); --n-400:oklch(68% .006 240);
  --n-300:oklch(78% .005 240); --n-200:oklch(86% .004 240); --n-100:oklch(92% .003 240);
  --n-050:oklch(97% .002 240); --n-000:oklch(100% 0 0);

  /* brand — 328.33deg */
  --brand-300:oklch(75% .200 328.33); --brand-400:oklch(71% .260 328.33);
  --brand-500:oklch(69% .3048 328.33); --brand-600:oklch(56% .240 328.33);
  --brand-700:oklch(46% .190 328.33);

  /* surfaces (light theme — the product's default) */
  --bg-app:oklch(98% .003 240);
  --bg-surface:oklch(100% 0 0);
  --bg-panel:oklch(99% .002 240);
  --bg-elevated:oklch(100% 0 0);
  --bg-hover:oklch(94% .006 240);
  --bg-active:oklch(90% .008 240);
  --bg-input:oklch(100% 0 0);
  --bg-sunken:oklch(96.5% .004 240);

  --text-primary:oklch(20% .014 240);
  --text-secondary:oklch(38% .014 240);
  --text-tertiary:oklch(48% .012 240);
  --text-disabled:oklch(72% .008 240);
  --text-inverse:oklch(98% .003 240);

  --border-subtle:oklch(90% .006 240);
  --border-default:oklch(82% .008 240);
  --border-strong:oklch(68% .010 240);

  /* semantic */
  --brand:oklch(48% .190 328.33);
  --brand-hover:oklch(40% .190 328.33);
  --brand-subtle:oklch(48% .190 328.33 / .12);
  --long:oklch(52.1% .099 175);
  --long-600:oklch(44% .090 175);
  --short:oklch(56.1% .200 355);
  --ai:oklch(55.1% .190 285);
  --success:oklch(52.1% .150 145);
  --warning:oklch(54.1% .115 75);
  --danger:oklch(64% .20 25);
  --on-trade:rgb(10,14,20);

  /* chart */
  --chart-grid:oklch(88% .006 240 / .7);
  --chart-axis:oklch(48% .012 240);
  --chart-crosshair:oklch(38% .014 240 / .5);
  --chart-up:oklch(52.1% .099 175);
  --chart-dn:oklch(56.1% .200 355);
  --chart-ma1:oklch(54.1% .115 75);
  --chart-ma2:oklch(55.1% .190 285);
  --chart-ma3:oklch(52.8% .106 230);
  --chart-vol-up:oklch(39.3% .049 175 / .6);
  --chart-vol-dn:oklch(42.7% .106 355 / .6);

  --shadow-1:0 1px 2px rgba(15,20,28,.06);
  --shadow-2:0 4px 12px rgba(15,20,28,.08);
  --shadow-3:0 12px 32px rgba(15,20,28,.14);

  /* type */
  --font-ui:'Pretendard Variable',pretendard,system-ui,-apple-system,'Segoe UI',sans-serif;
  --font-display:'IBM Plex Sans',var(--font-ui);
  --font-mono:'IBM Plex Mono',ui-monospace,monospace;

  --r-sm:3px; --r-md:4px; --r-lg:6px; --r-xl:8px;
  --header-h:48px;
  --rail-w:44px; --watch-w:226px; --order-w:262px;
}

*,*::before,*::after{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  height:100vh;overflow:hidden;display:flex;flex-direction:column;
  background:var(--bg-app);color:var(--text-primary);
  font-family:var(--font-ui);font-size:13px;line-height:1.45;
  font-variant-numeric:tabular-nums;
  -webkit-font-smoothing:antialiased;
}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
input{font:inherit;color:inherit}
::selection{background:var(--brand-subtle)}
:focus-visible{outline:2px solid var(--brand);outline-offset:1px;border-radius:2px}

.num{font-family:var(--font-mono);font-variant-numeric:tabular-nums;font-feature-settings:"zero" 1}
.up{color:var(--long)} .dn{color:var(--short)}
.eyebrow{
  font-size:11px;font-weight:500;letter-spacing:.44px;text-transform:uppercase;
  color:var(--text-tertiary);
}

/* ---------- scrollbars: thin, quiet ---------- */
.scroll{overflow:auto;scrollbar-width:thin;scrollbar-color:var(--border-default) transparent}
.scroll::-webkit-scrollbar{width:9px;height:9px}
.scroll::-webkit-scrollbar-thumb{background:var(--border-default);border-radius:9px;border:2px solid transparent;background-clip:content-box}
.scroll::-webkit-scrollbar-thumb:hover{background:var(--border-strong);background-clip:content-box}
.scroll::-webkit-scrollbar-track{background:transparent}

/* ==========================================================================
   Header — 48px, pure white, hairline bottom border
   ========================================================================== */
.hdr{
  height:var(--header-h);flex:0 0 var(--header-h);
  display:flex;align-items:center;gap:8px;
  padding:0 16px 0 12px;
  background:var(--bg-surface);border-bottom:1px solid var(--border-subtle);
  position:relative;z-index:40;
}
.brand{display:flex;align-items:center;gap:9px;padding-right:20px;height:47px;
  border-right:1px solid var(--border-subtle);flex:0 0 auto}
.brand svg{display:block;flex:0 0 auto}
.brand__word{
  font-family:var(--font-display);font-weight:700;font-size:13px;
  letter-spacing:.26px;color:var(--text-primary);white-space:nowrap;
}
.seg{
  display:flex;gap:2px;padding:2px;border:1px solid var(--border-subtle);
  border-radius:var(--r-md);background:var(--bg-surface);flex:0 0 auto;
}
.seg button{
  height:26px;padding:0 12px;border-radius:var(--r-sm);border:1px solid transparent;
  font-size:12.5px;font-weight:500;color:var(--text-secondary);
  display:inline-flex;align-items:center;gap:6px;white-space:nowrap;transition:background .12s,color .12s;
}
.seg button:hover{background:var(--bg-hover);color:var(--text-primary)}
.seg button[aria-pressed="true"]{
  background:var(--bg-elevated);border-color:var(--border-subtle);
  color:var(--text-primary);font-weight:600;box-shadow:var(--shadow-1);
}
.hdr__links{display:flex;align-items:center;gap:2px;margin-left:4px;flex:0 1 auto;min-width:0;overflow:hidden}
.hdr__links a{
  display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 9px;border-radius:var(--r-md);
  font-size:12.5px;color:var(--text-secondary);text-decoration:none;white-space:nowrap;transition:background .12s,color .12s;
}
.hdr__links a:hover{background:var(--bg-hover);color:var(--text-primary)}
.hdr__links svg{opacity:.62;flex:0 0 auto}
.hdr__links a:hover svg{opacity:.9}
.hdr__spacer{flex:1 1 auto;min-width:8px}
.hdr__tools{display:flex;align-items:center;gap:4px;flex:0 0 auto}
.iconbtn{
  width:28px;height:28px;border-radius:var(--r-md);display:grid;place-items:center;
  color:var(--text-secondary);transition:background .12s,color .12s;position:relative;
}
.iconbtn:hover{background:var(--bg-hover);color:var(--text-primary)}
.iconbtn[aria-pressed="true"]{background:var(--bg-active);color:var(--text-primary)}
.iconbtn .dot{position:absolute;top:5px;right:5px;width:6px;height:6px;border-radius:50%;
  background:var(--brand);box-shadow:0 0 0 2px var(--bg-surface)}
.langbtn{
  height:28px;padding:0 8px;border-radius:var(--r-md);font-size:12.5px;font-weight:500;
  color:var(--text-secondary);display:inline-flex;align-items:center;gap:5px;
}
.langbtn:hover{background:var(--bg-hover);color:var(--text-primary)}
.avatar{
  width:26px;height:26px;border-radius:50%;background:var(--brand);color:#fff;
  display:grid;place-items:center;font-size:11px;font-weight:700;margin-left:4px;
  font-family:var(--font-display);letter-spacing:.3px;flex:0 0 auto;
}

panel_css:
.panel{
  background:var(--bg-panel);border:1px solid var(--border-subtle);border-radius:var(--r-lg);
  display:flex;flex-direction:column;min-height:0;min-width:0;overflow:hidden;
}
.panel__hd{
  flex:0 0 auto;height:30px;display:flex;align-items:center;gap:8px;padding:0 10px;
  border-bottom:1px solid var(--border-subtle);background:var(--bg-panel);
}
.panel__hd .ttl{font-size:11.5px;font-weight:600;letter-spacing:.2px;color:var(--text-secondary);white-space:nowrap}
.panel__hd .sp{flex:1 1 auto}
.panel__bd{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}

copilot_css:
.fab{
  position:absolute;right:14px;bottom:14px;z-index:6;width:44px;height:44px;border-radius:50%;
  background:var(--brand);color:#fff;display:grid;place-items:center;
  box-shadow:0 6px 20px color-mix(in oklab,var(--brand) 40%,transparent),var(--shadow-2);
  transition:transform .16s,box-shadow .16s;
}
.fab:hover{transform:scale(1.05);box-shadow:0 8px 26px color-mix(in oklab,var(--brand) 52%,transparent),var(--shadow-3)}
.fab[aria-expanded="true"]{transform:scale(.92);opacity:.35}
.copilot{
  position:fixed;right:18px;bottom:76px;z-index:59;width:404px;max-height:min(760px,calc(100vh - 150px));
  background:var(--bg-elevated);border:1px solid var(--border-default);border-radius:var(--r-xl);
  box-shadow:var(--shadow-3);display:flex;flex-direction:column;overflow:hidden;
  transform:translateY(14px) scale(.985);opacity:0;pointer-events:none;transition:transform .18s cubic-bezier(.2,.8,.3,1),opacity .16s;
}
.copilot[data-open="true"]{transform:none;opacity:1;pointer-events:auto}
.copilot__hd{flex:0 0 auto;display:flex;align-items:center;gap:8px;padding:10px 11px;border-bottom:1px solid var(--border-subtle)}
.copilot__hd .ttl{font-family:var(--font-display);font-weight:700;font-size:13.5px;letter-spacing:.1px}
.copilot__hd .sp{flex:1 1 auto}
.copilot__tabs{flex:0 0 auto;display:flex;gap:2px;padding:8px 10px;border-bottom:1px solid var(--border-subtle);overflow-x:auto}
.copilot__tabs button{
  height:27px;padding:0 10px;border-radius:var(--r-md);font-size:11.5px;font-weight:500;
  color:var(--text-tertiary);border:1px solid var(--border-subtle);background:var(--bg-surface);
  white-space:nowrap;transition:.12s;
}
.copilot__tabs button:hover{background:var(--bg-hover);color:var(--text-primary)}
.copilot__tabs button[aria-pressed="true"]{background:var(--brand-subtle);color:var(--brand);
  border-color:color-mix(in oklab,var(--brand) 26%,transparent);font-weight:600}
.copilot__bd{flex:1 1 auto;min-height:0;overflow-y:auto;padding:11px;display:flex;flex-direction:column;gap:10px}
.cp-status{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.cp-chip{display:inline-flex;align-items:center;gap:5px;height:21px;padding:0 8px;border-radius:11px;
  font-size:10.5px;font-weight:700;letter-spacing:.3px;background:var(--bg-sunken);
  color:var(--text-tertiary);border:1px solid var(--border-subtle)}
.cp-chip--beta{background:color-mix(in oklab,var(--warning) 16%,transparent);color:oklch(42% .115 75);border-color:transparent}
.cp-chip--off{background:var(--bg-sunken);color:var(--text-tertiary)}
.cp-tools{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:11px;color:var(--text-tertiary)}
.cp-tools .t{display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 7px;border-radius:var(--r-sm);
  background:var(--bg-sunken);border:1px solid var(--border-subtle);font-family:var(--font-mono);font-size:10.5px}
.cp-tools .disc{background:color-mix(in oklab,var(--warning) 12%,transparent);border-color:transparent;
  color:oklch(42% .115 75);font-family:var(--font-ui);font-weight:500}
.bub{padding:9px 11px;border-radius:var(--r-md);font-size:12.5px;line-height:1.55}
.bub--sys{background:var(--bg-sunken);color:var(--text-secondary);font-family:var(--font-mono);font-size:11.5px}
.bub--sys b{font-weight:600;color:var(--text-primary)}
.bub--ai{border:1px solid var(--border-subtle);background:var(--bg-surface);color:var(--text-secondary)}
.bub--ai b{color:var(--text-primary);font-weight:600}
.bub__who{display:flex;align-items:center;gap:7px;margin-bottom:5px}
.bub__who .av{width:18px;height:18px;border-radius:var(--r-sm);background:var(--ai);color:#fff;
  display:grid;place-items:center;font-size:9px;font-weight:700;font-family:var(--font-display)}
.bub__who .nm{font-size:11.5px;font-weight:600;color:var(--text-secondary)}
.bub__who .ts{font-size:10.5px;color:var(--text-disabled);font-family:var(--font-mono);margin-left:auto}
.cp-quick{display:flex;flex-direction:column;gap:6px}
.cp-quick .hd{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:600;color:var(--brand)}
.cp-quick .grid{display:grid;grid-template-columns:1fr 1fr;gap:5px}
.cp-quick .grid button{
  text-align:left;padding:7px 9px;border:1px solid var(--border-subtle);border-radius:var(--r-md);
  background:var(--bg-surface);font-size:11.5px;font-weight:500;color:var(--text-secondary);
  display:flex;align-items:center;gap:7px;transition:.12s;
}
.cp-quick .grid button:hover{background:var(--bg-hover);border-color:var(--border-default);color:var(--text-primary)}
.cp-quick .grid button .n{font-size:9.5px;font-weight:700;color:var(--text-disabled);font-family:var(--font-mono)}
.cp-quick .grid button[aria-pressed="true"]{background:var(--brand-subtle);border-color:color-mix(in oklab,var(--brand) 26%,transparent);color:var(--brand)}
.cp-foot{flex:0 0 auto;border-top:1px solid var(--border-subtle);padding:9px 10px;display:flex;flex-direction:column;gap:7px}
.cp-cost{font-size:10.5px;color:var(--text-tertiary);display:flex;align-items:center;gap:6px}
.cp-cost b{font-family:var(--font-mono);font-weight:600;color:var(--text-secondary)}
.cp-input{display:flex;align-items:center;gap:8px}
.cp-input .box{
  flex:1 1 auto;height:38px;display:flex;align-items:center;padding:0 11px;
  background:var(--bg-input);border:1px solid var(--border-subtle);border-radius:var(--r-md);transition:.12s;
}
.cp-input .box:focus-within{border-color:var(--brand);box-shadow:0 0 0 3px var(--brand-subtle)}
.cp-input input{border:0;outline:0;background:none;width:100%;font-size:12.5px}
.cp-input input::placeholder{color:var(--text-disabled)}
.cp-input .send{width:38px;height:38px;border-radius:var(--r-md);background:var(--brand);color:#fff;
  display:grid;place-items:center;transition:.12s;flex:0 0 auto}
.cp-input .send:hover{background:var(--brand-hover)}
.cp-layers{display:flex;align-items:center;gap:6px;font-size:10.5px;font-weight:700;letter-spacing:.3px;
  text-transform:uppercase;color:var(--text-tertiary)}
.cp-layers .sp{flex:1 1 auto}

js_common:
$$('.seg button').forEach(function(b){
  b.addEventListener('click',function(){
    var p=b.parentNode; $$('button',p).forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('.chip').forEach(function(b){
  b.addEventListener('click',function(){
    var p=b.parentNode; $$('button',p).forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('.btab').forEach(function(b){
  b.addEventListener('click',function(){
    $$('.btab').forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('.watch__row').forEach(function(r){
  r.addEventListener('click',function(){
    $$('.watch__row').forEach(function(x){x.setAttribute('aria-selected','false');});
    r.setAttribute('aria-selected','true');
  });
});
$$('.rail button').forEach(function(b){
  b.addEventListener('click',function(){
    if(b.getAttribute('aria-label')==='Collapse sidebar') return;
    $$('.rail button').forEach(function(x){if(x.getAttribute('aria-label')!=='Collapse sidebar')x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('.drawrail button').forEach(function(b){
  b.addEventListener('click',function(){
    $$('.drawrail button').forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('#oeType button').forEach(function(b){
  b.addEventListener('click',function(){
    $$('#oeType button').forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('#cpTabs button').forEach(function(b){
  b.addEventListener('click',function(){
    $$('#cpTabs button').forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed','true');
  });
});
$$('.cp-quick .grid button').forEach(function(b){
  b.addEventListener('click',function(){
    var on=b.getAttribute('aria-pressed')==='true';
    $$('.cp-quick .grid button').forEach(function(x){x.setAttribute('aria-pressed','false');});
    b.setAttribute('aria-pressed',on?'false':'true');
  });
});
